phase1.code:
fn main() {
    // ---- The Borrow Checker in action ----

    // ---- Example 1: Valid borrowing ----
    let s = String::from("hello");
    let r1 = &s;
    let r2 = &s;
    println!("r1: {}, r2: {}", r1, r2);
    // r1 and r2 are dropped here
    let r3 = &mut s;  // Now we can borrow mutably
    println!("r3: {}", r3);

    // ---- Example 2: Invalid borrowing (won't compile) ----
    // let mut s2 = String::from("hello");
    // let r4 = &s2;
    // let r5 = &mut s2;  // ERROR! Can't borrow mutably while immutable borrow exists
    // println!("r4: {}", r4);

    // ---- Example 3: Nested scopes ----
    let mut s3 = String::from("hello");
    {
        let r6 = &mut s3;
        r6.push_str(" world");
    }  // r6 goes out of scope
    let r7 = &s3;  // Now we can borrow immutably
    println!("r7: {}", r7);

    // ---- Example 4: Function with borrowing ----
    let s4 = String::from("hello");
    let len = calculate_length(&s4);  // Borrow
    println!("Length: {}", len);
    // s4 is still valid here

    // ---- Example 5: Function with mutable borrowing ----
    let mut s5 = String::from("hello");
    change(&mut s5);  // Mutable borrow
    println!("s5: {}", s5);
    // s5 is still valid here

    // ---- Example 6: Dangling reference (won't compile) ----
    // let r8 = dangle();  // ERROR! Returns reference to local variable
}

fn calculate_length(s: &String) -> usize {
    s.len()
}

fn change(s: &mut String) {
    s.push_str(", world");
}

// fn dangle() -> &String {  // This won't compile!
//     let s = String::from("hello");
//     &s  // s is dropped here
// }  // Returning &s would be a dangling pointer

fn no_dangle() -> String {
    let s = String::from("hello");
    s  // Return ownership, not a reference
}

phase2.brokenCode:
fn main() {
    let r = dangle();
    println!("r: {}", r);
}

fn dangle() -> &String {
    let s = String::from("hello");
    &s  // ERROR! Returns reference to local variable
}

phase2.explanation:
You're trying to return a reference to a local variable that will be dropped.

**The fix:**
```rust
fn no_dangle() -> String {
    let s = String::from("hello");
    s  // Return ownership instead
}
```

**Rust-chan says:**
"The compiler is protecting you from a dangling pointer. `s` is dropped at the end of the function. Returning a reference to it would be invalid."
